Given this TypeScript function, refactor it by extracting the validation logic and the formatting logic into separate pure functions. Keep the same public API. Preserve all behavior:
```ts
function processOrder(order: { items: { price: number; qty: number }[]; tax: number; discount: number }): string {
  if (!order.items || !Array.isArray(order.items)) throw new Error('Invalid items');
  if (order.items.length === 0) throw new Error('No items');
  if (typeof order.tax !== 'number' || order.tax < 0) throw new Error('Invalid tax');
  let subtotal = 0;
  for (const item of order.items) {
    if (typeof item.price !== 'number' || item.price < 0) throw new Error('Invalid price');
    if (typeof item.qty !== 'number' || item.qty < 0) throw new Error('Invalid qty');
    subtotal += item.price * item.qty;
  }
  const total = subtotal + subtotal * order.tax - order.discount;
  return '$' + total.toFixed(2);
}
```

Refactor this monolithic TypeScript file into 4 properly separated modules:
- `models/user.ts` — User interface and types
- `utils/validation.ts` — Email, password, and username validation functions
- `repositories/userRepository.ts` — Data access layer with async operations
- `services/userService.ts` — Business logic layer

The monolith contains User model, 3 validation functions, 5 repository functions, and 4 service functions (register, login, updateProfile, deleteAccount). Preserve ALL behavior. Each module must have proper imports/exports. Return all 4 files.

```ts
interface User { id: string; username: string; email: string; passwordHash: string; createdAt: Date }
function isValidEmail(email: string): boolean { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) }
function isStrongPassword(pw: string): boolean { return pw.length >= 8 && /[A-Z]/.test(pw) && /[0-9]/.test(pw) }
function isValidUsername(u: string): boolean { return u.length >= 3 && u.length <= 30 && /^[a-zA-Z0-9_]+$/.test(u) }
const userDB: Map<string, User> = new Map()
async function findById(id: string): Promise<User | undefined> { return Promise.resolve(userDB.get(id)) }
async function findByEmail(email: string): Promise<User | undefined> { for (const u of userDB.values()) { if (u.email === email) return u } return undefined }
async function createUser(user: User): Promise<User> { userDB.set(user.id, user); return user }
async function updateUser(id: string, updates: Partial<User>): Promise<User | undefined> { const u = userDB.get(id); if (!u) return undefined; Object.assign(u, updates); return u }
async function deleteUser(id: string): Promise<boolean> { return userDB.delete(id) }
async function registerUser(username: string, email: string, password: string): Promise<User> { if (!isValidEmail(email)) throw new Error('Invalid email'); if (!isStrongPassword(password)) throw new Error('Weak password'); if (!isValidUsername(username)) throw new Error('Invalid username'); const existing = await findByEmail(email); if (existing) throw new Error('Email already registered'); const user: User = { id: Date.now().toString(36) + Math.random().toString(36).slice(2), username, email, passwordHash: 'hashed_' + password, createdAt: new Date() }; return createUser(user) }
async function loginUser(email: string, password: string): Promise<User> { const user = await findByEmail(email); if (!user) throw new Error('User not found'); if (user.passwordHash !== 'hashed_' + password) throw new Error('Invalid password'); return user }
async function updateProfile(id: string, data: { username?: string; email?: string }): Promise<User> { if (data.email && !isValidEmail(data.email)) throw new Error('Invalid email'); if (data.username && !isValidUsername(data.username)) throw new Error('Invalid username'); const updated = await updateUser(id, data); if (!updated) throw new Error('User not found'); return updated }
async function deleteAccount(id: string): Promise<void> { const deleted = await deleteUser(id); if (!deleted) throw new Error('User not found') }
```
